FUNCTION_BLOCK FB_S12
VAR_INPUT
    EStop_NC : BOOL;
    ResetBtn : BOOL;
    StartBtn : BOOL;
    DoorClosed : BOOL;
END_VAR
VAR_OUTPUT
    MachineRun : BOOL := FALSE;
    ShiftCount : UINT := 0;
    AlarmLamp : BOOL := FALSE;
    Status : WORD := WORD#16#0000;
END_VAR
VAR
    ResetTrig : R_TRIG;
    StartTrig : R_TRIG;
    ResetEdge : BOOL := FALSE;
    StartEdge : BOOL := FALSE;
    ResetConfirmed : BOOL := FALSE;
    RunCycles : UINT := 0;
END_VAR

(* Conflicting spec note: C10 requires AlarmLamp=FALSE on the first scans,
   but requirement 1 requires AlarmLamp=TRUE immediately when EStop_NC=FALSE.
   EStop safety priority is retained here. *)

(* Edge detection *)
ResetTrig(CLK := ResetBtn);
StartTrig(CLK := StartBtn);
ResetEdge := ResetTrig.Q;
StartEdge := StartTrig.Q;

(* Safety priority and reset/start sequence *)
IF NOT EStop_NC THEN
    MachineRun := FALSE;
    AlarmLamp := TRUE;
    Status := WORD#16#8B01;
    ResetConfirmed := FALSE;
ELSIF NOT DoorClosed THEN
    MachineRun := FALSE;
    AlarmLamp := FALSE;
    Status := WORD#16#8B03;
    ResetConfirmed := FALSE;
ELSE
    AlarmLamp := FALSE;

    IF NOT ResetConfirmed THEN
        MachineRun := FALSE;
        Status := WORD#16#8B02;
        IF ResetEdge THEN
            ResetConfirmed := TRUE;
            Status := WORD#16#0000;
        END_IF;
    ELSE
        Status := WORD#16#0000;
        IF StartEdge THEN
            MachineRun := TRUE;
        END_IF;
    END_IF;
END_IF;

(* ShiftCount: 60 s = 3000 scans of 20 ms. Only run time advances accumulator. *)
IF MachineRun THEN
    IF RunCycles >= UINT#2999 THEN
        RunCycles := 0;
        IF ShiftCount < UINT#65535 THEN
            ShiftCount := ShiftCount + UINT#1;
        END_IF;
    ELSE
        RunCycles := RunCycles + UINT#1;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
